arguments.command:
python -I -c 'import json,pathlib,collections
for p in sorted(pathlib.Path("/workspace/observed_run").glob("credit_traces.jsonl")):
 for line in p.open():
  x=json.loads(line); print("\ncall",x["call_index"])
  for r in x["rows"]:
   rew=sum(r["rewards"]); m=r["mask"]; ret=r["returns"]; adv=r["advantages"]
   if rew or x["call_index"]==0 and r["row"]==0:
    nz=[i for i,v in enumerate(m) if v]; last=max(nz); internal=[i for i in range(last+1) if not m[i]]
    runs=[]
    for i in internal:
     if not runs or i>runs[-1][-1]+1:runs.append([i])
     else:runs[-1].append(i)
    segs=[]
    for i in nz:
     if not segs or i>segs[-1][-1]+1:segs.append([i])
     else:segs[-1].append(i)
    print("row",r["row"],"reward",rew,"reward_nz",[(i,v) for i,v in enumerate(r["rewards"]) if v],"valid_len",last+1,"mask1",len(nz),"zero_runs",[(z[0],z[-1],len(z)) for z in runs],"gen_segments",[(s[0],s[-1],len(s),round(sum(ret[i] for i in s),4),round(min(adv[i] for i in s),4),round(max(adv[i] for i in s),4)) for s in segs],"ret_nonzero",sum(v!=0 for v in ret),"adv_range",(min(adv),max(adv)))
'

